      "answer": "1\u3001TCP\u5168\u8fde\u63a5\u626b\u63cf\u4f7f\u7528\u666e\u901aconnect()\u5b8c\u6210\u4e09\u6b21\u63e1\u624b\uff0c\u8fde\u63a5\u6210\u529f\u8bf4\u660e\u7aef\u53e3\u5f00\u653e\uff0c\u8fde\u63a5\u88ab\u62d2\u7edd\u901a\u5e38\u8bf4\u660e\u7aef\u53e3\u5173\u95ed\u3002SYN\u626b\u63cf\u53ea\u53d1\u9001SYN\u5305\uff0c\u82e5\u6536\u5230SYN+ACK\u8bf4\u660e\u7aef\u53e3\u5f00\u653e\uff0c\u968f\u540e\u53d1\u9001RST\u4e2d\u65ad\u8fde\u63a5\uff1b\u82e5\u6536\u5230RST\u5219\u8bf4\u660e\u7aef\u53e3\u5173\u95ed\uff0c\u56e0\u6b64\u5b83\u4e5f\u53eb\u534a\u5f00\u626b\u63cf\u3002\n2\u3001\u7528Windows\u5957\u63a5\u5b57API\u5b9e\u73b0\u5168\u8fde\u63a5\u626b\u63cf\u65f6\uff0c\u53ef\u5148WSAStartup()\uff0c\u518d\u4e3a\u6bcf\u4e2a\u76ee\u6807\u7aef\u53e3\u521b\u5efaTCP\u5957\u63a5\u5b57\uff0c\u586b\u5145\u76ee\u6807IP\u548c\u7aef\u53e3\u7684sockaddr_in\uff0c\u8c03\u7528connect()\u5c1d\u8bd5\u8fde\u63a5\u3002\u82e5connect()\u8fd4\u56de0\u5219\u8bb0\u5f55\u7aef\u53e3\u5f00\u653e\uff0c\u82e5\u8fd4\u56deSOCKET_ERROR\u5219\u7528WSAGetLastError()\u5224\u65ad\u8d85\u65f6\u3001\u62d2\u7edd\u6216\u4e0d\u53ef\u8fbe\uff0c\u6700\u540e\u5173\u95ed\u5957\u63a5\u5b57\u3002\n3\u3001\u4e3a\u4e86\u964d\u4f4e\u88ab\u7b80\u5355\u9632\u706b\u5899\u6216\u65e5\u5fd7\u89c4\u5219\u53d1\u73b0\u7684\u6982\u7387\uff0c\u53ef\u4ee5\u964d\u4f4e\u626b\u63cf\u901f\u7387\u3001\u968f\u673a\u5316\u7aef\u53e3\u987a\u5e8f\u3001\u8bbe\u7f6e\u5408\u7406\u8d85\u65f6\u3001\u9650\u5236\u5e76\u53d1\u7ebf\u7a0b\u6570\uff0c\u6216\u628a\u626b\u63cf\u5206\u6563\u5230\u591a\u4e2a\u65f6\u95f4\u7a97\u53e3\u4e2d\u6267\u884c\u3002\n\u8003\u5bdf\u70b9\uff1a\n1\u3001TCP\u4e09\u6b21\u63e1\u624b\u8fc7\u7a0b\u7684\u7406\u89e3\n2\u3001\u5957\u63a5\u5b57\u7f16\u7a0b\u57fa\u7840\uff08connect()\u51fd\u6570\u7684\u4f7f\u7528\uff09\n3\u3001\u7f51\u7edc\u5b89\u5168\u610f\u8bc6\uff08\u626b\u63cf\u884c\u4e3a\u7684\u9690\u853d\u6027\uff09"
