      "answer": "1\u3001\u53ef\u4f7f\u7528IP Helper API\u83b7\u53d6\u672c\u673a\u7f51\u5361\u4fe1\u606f\uff0c\u5e38\u7528\u51fd\u6570\u6709GetAdaptersInfo()\u548cGetAdaptersAddresses()\u3002\u7a0b\u5e8f\u5148\u5206\u914d\u7f13\u51b2\u533a\uff0c\u8c03\u7528\u51fd\u6570\u83b7\u53d6\u9002\u914d\u5668\u94fe\u8868\u6216\u6570\u7ec4\uff0c\u518d\u904d\u5386\u6bcf\u4e2a\u9002\u914d\u5668\u7ed3\u6784\u3002\n2\u3001\u89e3\u6790\u65f6\u4ece\u9002\u914d\u5668\u7ed3\u6784\u4e2d\u8bfb\u53d6\u7f51\u5361\u540d\u79f0\u3001\u63cf\u8ff0\u3001MAC\u5730\u5740\u3001IP\u5730\u5740\u3001\u5b50\u7f51\u63a9\u7801\u3001\u63a5\u53e3\u7c7b\u578b\u548c\u72b6\u6001\u7b49\u5b57\u6bb5\u3002\u53ef\u6839\u636eIfType\u3001OperStatus\u3001AdapterName\u6216Description\u4e2d\u7684\u5173\u952e\u5b57\u8fc7\u6ee4\u56de\u73af\u63a5\u53e3\u3001\u96a7\u9053\u63a5\u53e3\u548c\u90e8\u5206\u865a\u62df\u7f51\u5361\u3002\n3\u3001\u9ed8\u8ba4\u7f51\u5173\u548cDNS\u670d\u52a1\u5668\u4e5f\u53ef\u4ee5\u4eceGetAdaptersAddresses()\u8fd4\u56de\u7684\u7ed3\u6784\u4e2d\u83b7\u5f97\uff0c\u4f8b\u5982FirstGatewayAddress\u4fdd\u5b58\u7f51\u5173\u5730\u5740\uff0cFirstDnsServerAddress\u4fdd\u5b58DNS\u670d\u52a1\u5668\u94fe\u8868\uff1b\u904d\u5386\u8fd9\u4e9b\u94fe\u8868\u5e76\u628a\u4e8c\u8fdb\u5236\u5730\u5740\u8f6c\u6362\u6210\u5b57\u7b26\u4e32\u5373\u53ef\u663e\u793a\u3002\n\u8003\u5bdf\u70b9\uff1a\n1\u3001\u7f51\u7edc\u63a5\u53e3\u4fe1\u606f\u83b7\u53d6\u65b9\u6cd5\uff08\u5982GetAdaptersAddresses()\u51fd\u6570\uff09\n2\u3001\u6570\u636e\u89e3\u6790\u80fd\u529b\uff08\u4eceAPI\u8fd4\u56de\u7ed3\u6784\u4f53\u4e2d\u63d0\u53d6\u4fe1\u606f\uff09\n3\u3001\u7cfb\u7edf\u7f51\u7edc\u914d\u7f6e\u7684\u7406\u89e3"
