      "answer": "1\u3001\u670d\u52a1\u5668\u7ef4\u62a4\u4e00\u4e2a\u4e3bfd_set\u4fdd\u5b58\u76d1\u542c\u5957\u63a5\u5b57\u548c\u6240\u6709\u5728\u7ebf\u5ba2\u6237\u7aef\u5957\u63a5\u5b57\u3002\u7531\u4e8eselect()\u4f1a\u4fee\u6539\u4f20\u5165\u96c6\u5408\uff0c\u6bcf\u6b21\u8c03\u7528select()\u524d\u5e94\u628a\u4e3b\u96c6\u5408\u590d\u5236\u5230\u4e34\u65f6\u8bfb\u96c6\u5408\uff0c\u5e76\u8bbe\u7f6e\u8d85\u65f6\u65f6\u95f4\u6216\u4f20\u5165NULL\u8868\u793a\u4e00\u76f4\u7b49\u5f85\u3002\n2\u3001select()\u8fd4\u56de\u540e\uff0c\u5148\u7528FD_ISSET()\u5224\u65ad\u76d1\u542c\u5957\u63a5\u5b57\u662f\u5426\u53ef\u8bfb\uff0c\u82e5\u53ef\u8bfb\u8bf4\u660e\u6709\u65b0\u8fde\u63a5\uff0c\u8c03\u7528accept()\u5e76\u7528FD_SET()\u52a0\u5165\u4e3b\u96c6\u5408\u3002\u7136\u540e\u904d\u5386\u5ba2\u6237\u7aef\u5957\u63a5\u5b57\uff0c\u82e5\u67d0\u4e2a\u5957\u63a5\u5b57\u53ef\u8bfb\u5219\u8c03\u7528recv()\uff0c\u8fd4\u56de0\u6216\u9519\u8bef\u65f6\u5173\u95ed\u5e76FD_CLR()\u79fb\u9664\uff0c\u6536\u5230\u6b63\u5e38\u6570\u636e\u5219\u8fdb\u5165\u6d88\u606f\u5904\u7406\u3002\n3\u3001\u7fa4\u53d1\u65f6\u904d\u5386\u5728\u7ebf\u5ba2\u6237\u7aef\u96c6\u5408\uff0c\u628a\u6d88\u606fsend()\u7ed9\u9664\u53d1\u9001\u8005\u4ee5\u5916\u7684\u5176\u4ed6\u5ba2\u6237\u7aef\u3002\u53d1\u9001\u5931\u8d25\u8981\u5173\u95ed\u5bf9\u5e94\u5957\u63a5\u5b57\u5e76\u4ece\u96c6\u5408\u4e2d\u5220\u9664\u3002\u904d\u5386\u8fc7\u7a0b\u4e2d\u4fee\u6539\u96c6\u5408\u8981\u8c28\u614e\uff0c\u53ef\u4f7f\u7528\u6570\u7ec4\u6216\u5217\u8868\u4fdd\u5b58\u5ba2\u6237\u7aef\u5957\u63a5\u5b57\uff0c\u907f\u514d\u6f0f\u5904\u7406\u6216\u91cd\u590d\u5904\u7406\u3002\n\u8003\u5bdf\u70b9\uff1a\n1\u3001select()\u51fd\u6570\u7684\u4f7f\u7528\uff08FD_ZERO/FD_SET/FD_ISSET/FD_CLR\uff09\n2\u3001\u5355\u7ebf\u7a0b\u5e76\u53d1\u5904\u7406\u591a\u4e2a\u8fde\u63a5\n3\u3001\u5957\u63a5\u5b57\u96c6\u5408\u7684\u52a8\u6001\u7ef4\u62a4\n4\u3001\u7b80\u5355\u7684\u6d88\u606f\u5e7f\u64ad\u673a\u5236"
